function New-WinUtilBecamexLogo {
    <#
        .SYNOPSIS
            Creates the embedded BECAMEX Binh Phuoc logo for WinUtil.
    #>
    param(
        [double]$Size = 24,
        [double]$Width = 0,
        [double]$Height = 0,
        [switch]$Render,
        [switch]$FullArtwork
    )

    if ($Width -le 0) {
        $Width = $Size
    }
    if ($Height -le 0) {
        $Height = $Size
    }

    # The supplied SVG is gzip-compressed and embedded so the compiled script remains standalone.
    $compressedSvg = @'

'@
    $encodedBytes = [Convert]::FromBase64String($compressedSvg)
    $compressedStream = [System.IO.MemoryStream]::new($encodedBytes)
    $gzipStream = [System.IO.Compression.GZipStream]::new(
        $compressedStream,
        [System.IO.Compression.CompressionMode]::Decompress
    )
    $svgReader = [System.IO.StreamReader]::new($gzipStream, [System.Text.Encoding]::UTF8)
    [xml]$svg = $svgReader.ReadToEnd()
    $svgReader.Dispose()
    $gzipStream.Dispose()
    $compressedStream.Dispose()

    $viewbox = New-Object Windows.Controls.Viewbox
    $viewbox.Width = $Width
    $viewbox.Height = $Height
    $viewbox.Stretch = [Windows.Media.Stretch]::Uniform

    # The application navigation uses only the globe and BECAMEX wordmark.
    # Taskbar rendering requests FullArtwork so the supplied SVG remains unchanged.
    $canvas = New-Object Windows.Controls.Canvas
    $canvas.Width = 578
    $canvas.Height = if ($FullArtwork) { 444 } else { 360 }
    if (-not $FullArtwork) {
        $canvas.Clip = [Windows.Media.RectangleGeometry]::new([Windows.Rect]::new(0, 0, 578, 360))
    }

    foreach ($svgPath in $svg.svg.path) {
        $path = New-Object Windows.Shapes.Path
        $path.Data = [Windows.Media.Geometry]::Parse([string]$svgPath.d)
        $path.Fill = [System.Windows.Media.BrushConverter]::new().ConvertFromString([string]$svgPath.fill)

        $transform = [string]$svgPath.transform
        if ($transform -match '^translate\(\s*(?<x>-?[\d.]+)(?:,\s*|\s+)(?<y>-?[\d.]+)\s*\)$') {
            $path.RenderTransform = [Windows.Media.TranslateTransform]::new(
                [double]$Matches.x,
                [double]$Matches.y
            )
        }

        [void]$canvas.Children.Add($path)
    }

    $viewbox.Child = $canvas

    if (-not $Render) {
        return $viewbox
    }

    $viewbox.Measure([Windows.Size]::new($Width, $Height))
    $viewbox.Arrange([Windows.Rect]::new(0, 0, $Width, $Height))
    $viewbox.UpdateLayout()

    $renderTarget = New-Object Windows.Media.Imaging.RenderTargetBitmap(
        [int][Math]::Ceiling($Width),
        [int][Math]::Ceiling($Height),
        96,
        96,
        [Windows.Media.PixelFormats]::Pbgra32
    )
    $renderTarget.Render($viewbox)

    $encoder = [Windows.Media.Imaging.PngBitmapEncoder]::new()
    $encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($renderTarget))
    $imageStream = [System.IO.MemoryStream]::new()
    $encoder.Save($imageStream)
    $imageStream.Position = 0

    $image = [Windows.Media.Imaging.BitmapImage]::new()
    $image.BeginInit()
    $image.StreamSource = $imageStream
    $image.CacheOption = [Windows.Media.Imaging.BitmapCacheOption]::OnLoad
    $image.EndInit()
    $imageStream.Dispose()

    if ($image.CanFreeze) {
        $image.Freeze()
    }

    return $image
}
